import{_ as t,o as a,c as s,aj as p}from"./chunks/framework.BdtAaXf2.js";const i="/assets/image-20260528224402245.CJ3PSgJs.png",o="/assets/image-20260528230858244.DlexsyW8.png",r="/assets/image-20260528231007123.CB0eI2l2.png",e="/assets/image-20260528231118208.BIiwvUvV.png",g="/assets/image-20260528231159825.DIpq4AcO.png",l="/assets/image-20260528231551003.Bp--AIja.png",b="/assets/PixPin_2026-05-28_23-16-41.Di1lknt4.gif",c="/assets/image-20260528233438138.5a-jfk9p.png",m="/assets/image-20260528233528999.D42iAebD.png",_="/assets/image-20260528233745634.D_LB3qwE.png",h="/assets/image-20260528234758710.CguHJvqG.png",T="/assets/PixPin_2026-05-29_09-35-07.Dokp5wOR.gif",u="/assets/image-20260529093727085.BWk1h_6m.png",A="/assets/image-20260529093917293.DoUOvAKh.png",I="/assets/image-20260529094337156.B8rYlJlT.png",d="/assets/image-20260529094442901.DEOc-pwT.png",k="/assets/image-20260529100033474.Sh57jOrH.png",w="/assets/image-20260529100145461.DOaK2PEY.png",f="/assets/image-20260529100326026.Y8oA1Zcj.png",B=JSON.parse('{"title":"美团 Tabbit 的这几个功能，就是最好的学习搭子","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/美团Tabbit的这几个功能就是最好的学习搭子/美团Tabbit这个多Tab总结功能就是最好的学习搭子.md","filePath":"AI人工智能/美团Tabbit的这几个功能就是最好的学习搭子/美团Tabbit这个多Tab总结功能就是最好的学习搭子.md","lastUpdated":1780052585000,"__rawMarkdown":"# 美团 Tabbit 的这几个功能，就是最好的学习搭子\\n\\n## 前言\\n\\n如果说过去的浏览器只是“打开网页的工具”，那么 AI 时代的浏览器，正在变成一个能理解上下文、能帮你整理信息、还能替你执行任务的工作入口。\\n\\n**Tabbit 就是这样一款主打 AI 智能体验的浏览器。**\\n\\n它不是简单地在浏览器侧边栏里塞进一个聊天窗口，而是把 **网页、截图、划词内容、多个标签页，甚至自动化任务** 都纳入到 AI 可理解的上下文里。\\n\\n对于经常查资料、看文档、学新技术、做信息整理的人来说，这种体验非常像身边多了一个随叫随到的学习搭子。\\n\\n我最近重点体验了 Tabbit 的几个功能：妙招、Chat、多 Tab 总结和自动任务。用下来最明显的感受是，它把“查资料”和“整理资料”之间的距离缩短了很多。以前我们需要在网页之间来回切换、复制粘贴、手动汇总，再把材料交给 AI；现在很多时候可以直接在浏览器里完成。\\n\\n下面就结合我的使用过程，聊聊这些功能为什么适合用来学习和办公。\\n\\n---\\n\\n## 下载安装\\n\\n打开 Tabbit 官网地址：https://www.tabbit-ai.com/\\n\\nTabbit 提供 **国内版** 和 **国际版**，用户可以根据自己的使用环境选择对应版本下载安装。\\n\\n国内用户可以优先选择国内版，模型、访问速度和账号体系会更符合本地使用习惯。\\n\\n![](assets/image-20260528224402245.png)\\n\\n安装完成后，整体界面和常见浏览器比较接近，上手成本不高。\\n\\n真正值得关注的，是右上角的两个入口：\\n\\n- **妙招**\\n- **Chat**\\n\\n这两个入口基本覆盖了 Tabbit 作为 AI 浏览器最核心的使用场景。\\n\\n## 妙招\\n\\n先看 **妙招**。\\n\\n你可以把“妙招”理解成浏览器里的 **AI 技能**，类似现在很多 AI 产品里的 Skill。\\n\\n它可以把一些固定、常用、重复的操作路径封装起来，让用户在需要的时候快速调用。\\n\\n比如，有些人每天都要看行业资讯，有些人经常要整理网页摘要，有些人需要固定格式的内容生成。如果每次都重新写提示词、重新打开网页、重新组织流程，其实很浪费时间。妙招的价值就在于，把这些重复动作沉淀成一个可以复用的入口。\\n\\nTabbit 既支持用户自己创建妙招，也提供了 **妙招广场**。你可以直接使用其他用户上传和发布的妙招，先从现成案例里找灵感，再根据自己的工作流继续调整。\\n\\n![](assets/image-20260528230858244.png)\\n\\n点开之后，可以看到自己创建的妙招，以及 **全部妙招** 和 **创建妙招** 两个入口。\\n\\n![](assets/image-20260528231007123.png)\\n\\n我先进入 **全部妙招** 看了一下。\\n\\n![](assets/image-20260528231118208.png)\\n\\n这里就是妙招广场，里面放了不少用户上传和发布的妙招。你可以根据自己的需求选择添加。我这里添加了一个 **大厂资讯的妙招彩蛋**。\\n\\n![](assets/image-20260528231159825.png)\\n\\n添加完成后，新建一个标签页，在搜索框中输入 `/`，就会出现可调用的 **妙招选项**。\\n\\n![](assets/image-20260528231551003.png)\\n\\n---\\n\\n接下来看看这个妙招实际执行时会发生什么。\\n\\n![](assets/PixPin_2026-05-28_23-16-41.gif)\\n\\n可以看到，妙招不是一个静态模板，而是会按照设定好的流程去完成对应任务。\\n\\n对于学习和办公来说，这类功能特别适合处理 **“高频但不复杂”** 的事情，比如：\\n\\n- 资讯汇总\\n- 网页摘要\\n- 资料检索\\n- 格式化输出\\n\\n如果你还没有明确的使用场景，也可以先逛一逛妙招广场。很多时候看到别人怎么用，就能想到自己的工作流里有哪些步骤可以被自动化。\\n\\n> 简单来说，妙招更像是把你的常用提示词和操作流程做成一个快捷入口。\\n\\n## Chat\\n\\n再来看右上角的 **Chat**。\\n\\n在浏览网页时，点开 Chat 按钮，当前页面会默认作为本次对话的上下文。\\n\\n也就是说，你不需要先复制网页内容，再粘贴给 AI，它已经知道你正在看的页面是什么。\\n\\n![](assets/image-20260528233438138.png)\\n\\n你可以直接围绕当前页面提问，比如：\\n\\n- 帮我总结这篇文章的核心观点；\\n- 这段内容适合初学者怎么理解；\\n- 这篇文档里有哪些关键参数；\\n- 帮我把这个页面整理成学习笔记。\\n\\n除了页面级提问，它还支持 **划词提问** 和 **截图提问**，这两个能力在学习场景里非常实用。\\n\\n**划词提问**\\n\\n![](assets/image-20260528233528999.png)\\n\\n---\\n\\n**截图提问**\\n\\n![](assets/image-20260528233745634.png)\\n\\n划词提问适合处理局部概念。比如你在看技术文档时，遇到一个不熟悉的参数、术语或 API，可以直接选中那一段让 Tabbit 解释，不用打断当前阅读节奏。\\n\\n截图提问则更适合处理 **视频、图表、界面和报错信息**。\\n\\n比如看课程视频时，老师在屏幕上展示了一段配置；或者你在网页里看到一张流程图，但文字说明不够清楚，都可以直接截图问。\\n\\n相比手动描述问题，截图能提供更完整的视觉上下文，AI 的回答也更容易贴近你真正想问的点。\\n\\n![](assets/image-20260528234758710.png)\\n\\n这也是我觉得 Tabbit 适合做“学习搭子”的原因之一：\\n\\n> 它不是等你把问题整理得很完整之后才介入，而是在你阅读、观看、理解的过程中，随时补上解释、总结和追问。\\n\\n## 多 Tab 总结\\n\\n接下来是我最推荐的功能：**多 Tab 总结**。\\n\\n过去大多数网页 AI 总结工具，处理的信息都比较单一，通常只能总结当前页面。这个能力当然有用，但在真实学习场景里经常不够。\\n\\n因为一个知识点往往不会只存在于一个网页里。\\n\\n比如你想学习某个技术框架，可能会同时打开：\\n\\n- 官方文档\\n- 教程文章\\n- GitHub 示例\\n- 问答页面\\n- 相关博客\\n\\n每个页面都只提供了一部分信息，真正有价值的是把这些分散内容放在一起理解。\\n\\n以前要做到这一点，通常只能手动把多个网页的信息复制出来，汇总到一个文档里，再丢给 AI 提问。这个过程不仅麻烦，还容易遗漏上下文。资料越多，整理成本越高，最后往往还没开始学习，人已经先被资料管理消耗掉了。\\n\\nTabbit 的思路更直接：\\n\\n> **它可以把多个已打开的标签页看成你的上下文。**\\n\\n也就是说，你可以直接针对当前打开的一组网页提问，而不是一个页面一个页面地总结。\\n\\n操作也很简单：点击对话框里的 `@` 符号，然后选择 **所有已打开的标签页**。\\n\\n我这里输入的是：\\n\\n> 帮我总结 Navigation 的使用技巧\\n\\n![](assets/PixPin_2026-05-29_09-35-07.gif)\\n\\n接下来只需要等待 Tabbit 获取多个标签页里的关键信息，并生成总结。\\n\\n![](assets/image-20260529093727085.png)\\n\\n---\\n\\n这个功能特别适合几类场景：\\n\\n- **学新框架**：同时总结官方文档、示例代码和教程文章；\\n- **做选型调研**：对比多个产品页、评测页和社区讨论；\\n- **写文章前准备资料**：快速整理多个资料来源里的核心信息；\\n- **排查问题**：把搜索结果、Stack Overflow、GitHub Issue 和官方说明放在一起分析。\\n\\n它解决的不是“帮我总结一篇文章”这么简单的问题，而是帮你把 **分散在多个网页里的信息** 合并成一个 **可对话的知识上下文**。\\n\\n更进一步，Tabbit 最近更新的 **智能代理** 模式，还支持把整理结果生成文件，并直接下载到本地。\\n\\n![](assets/image-20260529093917293.png)\\n\\n---\\n\\n不一会儿，就可以点击下载了。\\n\\n![](assets/image-20260529094337156.png)\\n\\n我打开看了一下，内容洋洋洒洒有三千多字。如果完全靠自己整理，需要在多个页面之间来回切换，还要筛选重点、合并重复信息、重新组织结构。这个过程至少要花不少时间。\\n\\n![](assets/image-20260529094442901.png)\\n\\n用好这个功能，学习效率会明显提升。\\n\\n尤其是面对资料很多、概念比较密集的主题时，**多 Tab 总结可以先帮你搭一个框架，再由你继续追问细节**。这样学习就不是从一堆网页里硬啃，而是先拥有一个清晰的入口。\\n\\n## 自动任务\\n\\n最后，再介绍一个我常用的功能：**自动任务**。\\n\\n自动任务可以让 Tabbit 在指定时间执行某些固定操作。\\n\\n比如我经常需要关注 AI 科技资讯，就可以设置一个任务，让 Tabbit 定时从几个科技媒体获取最新内容。\\n\\n我使用的任务示例是：\\n\\n> 帮我从以下几个科技媒体获取最新的 AI 科技资讯：\\n>\\n> - 少数派：https://sspai.com/\\n> - 虎嗅：https://www.huxiu.com/\\n> - 36 氪：https://www.36kr.com/\\n\\n![](assets/image-20260529100033474.png)\\n\\n这个功能不是简单地从已有语料里生成一段“看起来像资讯”的内容，而是真的会像用户一样打开网页、读取页面信息，再把结果整理出来。\\n\\n![](assets/image-20260529100145461.png)\\n\\n---\\n\\n对于需要长期关注某些网站、栏目或领域的人来说，自动任务非常有价值。\\n\\n它适合处理那些 **“每天都要做，但每天都差不多”** 的事情，比如：\\n\\n- 每天早上汇总行业新闻；\\n- 定期查看竞品网站更新；\\n- 追踪某个技术博客或产品更新日志；\\n- 收集指定关键词相关的最新内容；\\n- 把固定来源的信息整理成日报或周报。\\n\\n更重要的是，自动任务对一些需要登录的网站也能发挥作用。只要你在浏览器里已经登录，Tabbit 就有机会基于真实页面内容完成读取和整理。这样可以减少 AI 凭旧资料回答、凭印象补全信息的问题。\\n\\n![](assets/image-20260529100326026.png)\\n\\n可以看到，整理出来的信息来自真实页面，这对资讯类、调研类和资料收集类任务都很关键。\\n\\n> 对需要长期跟踪信息源的人来说，自动任务的价值不只是省时间，更是让信息获取变得稳定、持续、可复用。\\n\\n## 总结\\n\\n这次体验下来，我觉得 Tabbit 最适合的用户，不只是想“找一个带 AI 的浏览器”的人，而是那些每天都要和信息打交道的人。\\n\\n如果你经常学习新技术、阅读英文文档、整理行业资讯、写文章、做调研，Tabbit 的优势会比较明显：\\n\\n- **妙招** 适合把高频流程沉淀成可复用的技能；\\n- **Chat** 适合在阅读过程中随时解释、总结和追问；\\n- **多 Tab 总结** 适合把分散资料合并成统一上下文；\\n- **自动任务** 适合定期抓取和整理固定来源的信息。\\n\\n对我来说，其中最有价值的还是多 Tab 总结。因为真实学习从来不是只看一个页面，而是在多个来源之间建立联系。Tabbit 把这个过程放进浏览器里，让 AI 更贴近我们的实际工作流。\\n\\n如果你也经常一边开十几个标签页，一边担心自己 **看不完、理不清、记不住**，那么 Tabbit 真的值得试试。\\n\\n用好了，它不只是一个浏览器，更像是一个能帮你梳理信息、陪你推进学习的搭子。\\n"}'),q={name:"AI人工智能/美团Tabbit的这几个功能就是最好的学习搭子/美团Tabbit这个多Tab总结功能就是最好的学习搭子.md"};function P(x,n,C,D,S,v){return a(),s("div",null,[...n[0]||(n[0]=[p("",115)])])}const H=t(q,[["render",P]]);export{B as __pageData,H as default};
